export async function getAllProducts() {
  // Simulate database delay
  await new Promise((resolve) => setTimeout(resolve, 100))

  return [
    { id: 1, name: 'Laptop', price: 999 },
    { id: 2, name: 'Phone', price: 699 },
    { id: 3, name: 'Tablet', price: 499 },
    { id: 4, name: 'Headphones', price: 199 },
    { id: 5, name: 'Watch', price: 299 },
  ]
}

/**
 * Pull the latest pricing / inventory / availability from the upstream ERP/PIM
 * and write it into our own store. Stands in for the real sync job, which can
 * touch thousands of SKUs.
 */
export async function pullUpstreamCatalog() {
  // Simulate the upstream round-trip
  await new Promise((resolve) => setTimeout(resolve, 300))

  return { syncedSkus: 5 }
}

